<?php $policy=$comm['automation']??array(); ?>
<?php if(empty($policy['available'])): ?><div class="notice">Automation plans are not available yet. Contact your Administrator.</div><?php else: ?>
<section class="comm-card"><h2><?= $h($policy['plan']['name']??'Automation plan'); ?></h2><p class="muted"><?= $subscribed?'Your subscription expires '.$h($expiry).'.':'Choose a plan and wait for Administrator approval.'; ?></p><div class="metric"><?= (int)$policy['used_workflows']; ?> / <?= (int)($policy['plan']['max_workflows']??0); ?></div><p class="muted">Registered workflows · on and off workflows both use a slot. Archive one to free its slot. SMS and email messages use their own channel credits.</p><?php if($subscribed):$form('communication_toggle','automation',array('enabled'=>$m['merchant_enabled']?'':'1')); ?><label class="row"><input type="checkbox" class="switch" <?= $m['merchant_enabled']?'checked':''; ?> onchange="this.form.submit()" aria-label="Enable Automation"> <?= $m['merchant_enabled']?'Automation is on':'Automation is off'; ?></label><?= form_close(); ?><?php endif; ?></section>
<div class="comm-grid"><?php foreach($policy['plans'] as $plan): ?><section class="comm-card"><span class="comm-badge"><?= $h($plan['name']); ?></span><div class="metric"><?= (int)$plan['max_workflows']; ?> automations</div><p class="muted">Templates included: <?php $templateNames=array();foreach($plan['template_keys'] as $key)if(isset($policy['all_templates'][$key]))$templateNames[]=$policy['all_templates'][$key]['name'];echo $h(implode(', ',$templateNames)?:'No templates currently available'); ?>.</p><?php if(!(int)$plan['monthly_kobo'] && !(int)$plan['annual_kobo']): ?><p class="muted">Contact your Administrator for pricing and assisted activation.</p><?php else:$form('communication_request','automation',array('purpose'=>'subscription','request_key'=>hash('sha256',$purchase_key.'|'.$plan['plan_key']),'plan_key'=>$plan['plan_key'])); ?><?php foreach(array('monthly'=>'Monthly · 30 days','annual'=>'Annual · 365 days') as $period=>$label):if(!(int)$plan[$period.'_kobo'])continue; ?><label class="choice"><input type="radio" name="period" value="<?= $h($period); ?>" required> <?= $h($label); ?> · <?= $money($plan[$period.'_kobo']); ?></label><?php endforeach; ?><label>Contact email<input type="email" name="email" value="<?= $h($messaging['account']['reply_to']??''); ?>" required></label><?php if($m['allowed'] && $c['enabled']): ?><div class="row" style="margin-top:15px"><button class="btn secondary">Request bank payment</button><?php foreach($messaging['providers']??array() as $provider): ?><button class="btn" name="provider" value="<?= $h($provider); ?>" data-checkout>Pay with <?= $h(ucfirst($provider)); ?></button><?php endforeach; ?></div><?php endif; ?><?= form_close();endif; ?></section><?php endforeach; ?></div>
<?php endif; ?>
